/* ── Post List ──────────────────────────────────── */

.post-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

.post-item {
  border-bottom: 1px solid var(--border);
  padding-bottom: 2.5rem;
}

.post-item:last-child {
  border-bottom: none;
}

.post-meta {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 0.8rem;
}

.post-date, .post-reading-time {
  font-size: 0.8rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-family: var(--mono);
  color: var(--text-dim);
}

.post-tags {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.tag-pill {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-family: var(--mono);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.2em 0.6em;
  color: var(--text-dim);
  transition: border-color var(--transition), color var(--transition);
}

.tag-pill:hover {
  border-color: var(--accent);
  color: var(--text-primary);
}

.post-title {
  font-size: clamp(1.2rem, 2.5vw, 1.6rem);
  font-weight: 200;
  margin-bottom: 0.6rem;
}

.post-title a {
  color: var(--text-primary);
  border: none;
}

.post-title a:hover {
  color: var(--text-bright);
  border: none;
}

.post-excerpt {
  color: var(--text-dim);
  font-size: 0.9rem;
  line-height: 1.7;
}

/* ── Tag list / Tag cloud ───────────────────────── */

.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.tag-cloud .tag-pill {
  font-size: 0.8rem;
  padding: 0.3em 0.8em;
}

.tag-cloud-count {
  color: var(--text-dim);
  margin-left: 0.3em;
}

.tag-list {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1rem;
}

.tag-list-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1rem 1.2rem;
  transition: border-color var(--transition);
}

.tag-list-item:hover {
  border-color: var(--border-bright);
}

.tag-list-link {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.8rem;
  border: none;
  color: var(--text-primary);
}

.tag-list-link:hover {
  border: none;
  color: var(--text-bright);
}

.tag-list-name {
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  text-transform: uppercase; /* same display convention as .tag-pill (#737) */
}

/* The tag page heading: shown the way the pill shows the tag. Display only;
   the tag's name is unchanged in the data, the title and the feed label. */
.tag-title {
  text-transform: uppercase;
}

.tag-back {
  margin: 0.6rem 0 0;
  font-size: 0.8rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-family: var(--mono);
}

.tag-list-count {
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  font-family: var(--mono);
  color: var(--text-dim);
}

.tag-list-description {
  margin-top: 0.5rem;
  font-size: 0.8rem;
  color: var(--text-dim);
  line-height: 1.5;
}

/* ── Single Post ────────────────────────────────── */

.post-header {
  margin-bottom: 3rem;
}

.post-header h1 {
  margin-bottom: 1rem;
}

.post-content {
  font-size: 1.05rem;
  line-height: 1.8;
  color: var(--text-secondary);
}

.post-content h2 {
  margin: 2.5rem 0 1rem;
}

.post-content h3 {
  margin: 2rem 0 0.8rem;
}

.post-content ul, .post-content ol {
  margin: 1rem 0 1.2rem 1.5rem;
}

.post-content li {
  margin-bottom: 0.4rem;
}

.post-content a {
  color: var(--text-dim);
  border-bottom: 1px solid var(--border);
  animation: text-thermal 8s ease-in-out infinite alternate,
             border-thermal 8s ease-in-out infinite alternate;
}

.post-content a:hover {
  color: var(--text-bright);
  border-bottom-color: var(--text-bright);
}

/* HTML Embed wrapper emitted by the Decap "HTML Embed" editor component
   (admin/editor-component-html-embed.js). Vertical rhythm only — author
   markup inside the wrapper styles itself. */
.post-embed {
  display: block;
  margin: 1.5rem 0;
}

.featured-image {
  /* Block, not the inline default: an inline image sits on a text baseline, so
     its line box added a descender strip under the picture (#737). */
  display: block;
  width: 100%;
  max-height: 400px;
  object-fit: cover;
  border-radius: var(--radius-lg);
  margin-bottom: 2rem;
  border: 1px solid var(--border);
}

/* In the post header the image's own 2rem stacked on `.post-header`'s 3rem and
   left about 90px before the body (#737). The header's margin is the one gap;
   the Decap preview pane renders the image outside a header and keeps 2rem. */
.post-header .featured-image {
  margin-bottom: 0;
}

/* ── Projects Grid ──────────────────────────────── */

.projects-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.5rem;
}

.project-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.8rem;
  transition: border-color var(--transition), transform var(--transition);
  position: relative;
  overflow: hidden;
}

.project-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, var(--accent-glow), transparent 70%);
  opacity: 0;
  transition: opacity var(--transition);
}

.project-card:hover {
  border-color: var(--border-bright);
  transform: translateY(-2px);
}

.project-card:hover::before {
  opacity: 1;
}

.project-card-inner {
  position: relative;
  z-index: 1;
}

.project-card h3 {
  font-size: 1.1rem;
  margin-bottom: 0.8rem;
}

.project-card h3 a {
  color: var(--text-primary);
  border: none;
}

.project-tech {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-family: var(--mono);
  color: var(--accent);
  margin-bottom: 0.8rem;
}

.project-description {
  font-size: 0.875rem;
  color: var(--text-dim);
  line-height: 1.7;
  margin-bottom: 1rem;
}

.project-link {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-family: var(--mono);
  color: var(--text-dim);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.4em 0.9em;
  transition: border-color var(--transition), color var(--transition);
}

.project-link:hover {
  border-color: var(--accent);
  color: var(--text-primary);
}

.featured-badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-family: var(--mono);
  color: var(--accent);
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  padding: 0.2em 0.5em;
  z-index: 2;
}

/* ── Page content ───────────────────────────────── */

.page-content {
  font-size: 1.05rem;
  line-height: 1.8;
  color: var(--text-secondary);
}

.page-content h2 {
  margin: 2.5rem 0 1rem;
}

.page-content ul, .page-content ol {
  margin: 1rem 0 1.2rem 1.5rem;
}

.page-content li {
  margin-bottom: 0.4rem;
}

.page-content a {
  color: var(--text-dim);
  border-bottom: 1px solid var(--border);
  animation: text-thermal 8s ease-in-out infinite alternate,
             border-thermal 8s ease-in-out infinite alternate;
}

/* ── Page not found ─────────────────────────────── */

.page-not-found {
  text-align: center;
  padding-top: 2rem;
  border-bottom: none;
}

.page-not-found__code {
  font-family: var(--mono);
  font-size: clamp(4rem, 14vw, 8rem);
  font-weight: 200;
  letter-spacing: 0.08em;
  color: var(--accent);
  line-height: 1;
  margin: 0;
  animation: text-thermal 8s ease-in-out infinite alternate;
}

.page-not-found__message {
  font-size: 0.95rem;
  letter-spacing: 0.02em;
  color: var(--text-dim);
  margin-top: 1rem;
}

.page-not-found__actions {
  text-align: center;
  margin-top: 2rem;
}

/* ── Utility ────────────────────────────────────── */

/* Skip link: off-screen until keyboard focus, then pinned top-left. */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1000;
  transform: translateY(-120%);
  padding: 0.6rem 1rem;
  background: var(--bg-2);
  color: var(--text-bright);
  border: 1px solid var(--border);
  font-family: var(--mono);
  font-size: 0.8rem;
}

.skip-link:focus {
  transform: translateY(0);
}

main:focus {
  outline: none;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border-width: 0;
}

.text-center { text-align: center; }
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }

/* ── Feed Link (RSS icon) ───────────────────────── */

.feed-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  vertical-align: middle;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-dim);
  background: transparent;
  text-decoration: none;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}

.feed-link:hover,
.feed-link:focus-visible {
  color: #ee802f; /* canonical RSS orange — appears only on intent */
  border-color: #ee802f;
  background: rgb(238 128 47 / 8%);
}

.feed-link-icon {
  width: 0.95rem;
  height: 0.95rem;
}

.page-header-with-feed {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.6rem 0.9rem;
  margin-bottom: 0.5rem;
}

.page-header-with-feed h1,
.page-header-with-feed h2 {
  margin-bottom: 0;
}

/* ── Share Row ──────────────────────────────────── */

.share-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-top: 3rem;
  padding-top: 1.4rem;
  border-top: 1px solid var(--border);
}

.share-row-label {
  font-size: 0.8rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-family: var(--mono);
  color: var(--text-dim);
  margin-right: 0.4rem;
}

.share-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.9rem;
  height: 1.9rem;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  text-decoration: none;
  position: relative;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}

.share-link svg {
  width: 0.95rem;
  height: 0.95rem;
  display: block;
}

.share-link:hover,
.share-link:focus-visible {
  color: var(--text-bright);
  border-color: var(--border-bright);
  background: var(--bg-2);
}

/* `.share-link svg` above is (0,1,1); a bare `.share-icon-success` (0,1,0)
   lost to it, so the idle copy button showed the link AND the check (#727).
   Keep this at least (0,2,0). */
.share-link .share-icon-success { display: none; }
.share-copy.share-copied .share-icon-default { display: none; }
.share-copy.share-copied .share-icon-success { display: block; }

.share-copy.share-copied {
  color: var(--text-bright);
  border-color: var(--accent);
}

/* The Mastodon instance field (#727): replaces a bare window.prompt(). It opens
   on its own line under the icons. A `display` here beats the UA's
   `[hidden] { display: none }`, so the hidden state is spelled out. */
.share-mastodon-form {
  flex: 1 0 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

.share-mastodon-form[hidden],
.share-mastodon-error[hidden] {
  display: none;
}

.share-mastodon-form label {
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  font-family: var(--mono);
  color: var(--text-dim);
}

.share-mastodon-form input {
  flex: 1 1 11rem;
  min-width: 0;
  min-height: 2.25rem;
  padding: 0.3rem 0.65rem;
  border: 1px solid var(--border-bright);
  border-radius: var(--radius);
  background: var(--bg-1);
  color: var(--text-primary);
  font: inherit;
}

.share-mastodon-form input:focus-visible,
.share-mastodon-form button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.share-mastodon-form button {
  min-height: 2.25rem;
  padding: 0 0.9rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: transparent;
  color: var(--text-dim);
  font: inherit;
  font-size: 0.9rem;
  cursor: pointer;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}

.share-mastodon-form button:hover,
.share-mastodon-form button:focus-visible {
  color: var(--text-bright);
  border-color: var(--border-bright);
  background: var(--bg-2);
}

.share-mastodon-error {
  flex: 1 0 100%;
  margin: 0;
  color: var(--text-bright);
  font-size: 0.875rem;
}

/* Touch targets (#727): 1.9rem (~30px) is under the 44px minimum (WCAG 2.5.5,
   Apple HIG), so on a phone or any coarse pointer each button becomes a real
   2.75rem (44px) box. The icon stays 0.95rem, and the tighter gap and label
   margin keep all five buttons on one line down to a 360px viewport. Desktop
   (fine pointer, wider than a phone) is untouched. */
@media (pointer: coarse), (width <= 640px) {
  .share-row {
    gap: 0.25rem;
  }

  .share-row-label {
    margin-right: 0.25rem;
  }

  .share-link {
    width: 2.75rem;
    height: 2.75rem;
  }

  .share-mastodon-form input,
  .share-mastodon-form button {
    min-height: 2.75rem;
  }
}

@media (forced-colors: active) {
  .feed-link,
  .share-link,
  .share-mastodon-form button {
    border-color: ButtonText;
  }

  .feed-link:hover,
  .feed-link:focus-visible,
  .share-link:hover,
  .share-link:focus-visible {
    border-color: Highlight;
    color: Highlight;
  }
}

/* ── Reduced motion ─────────────────────────────── */

/* The glow, thermal color cycles and link shimmer all run forever. Honor the
   OS "reduce motion" setting by stopping every animation and parking the
   full-viewport glow at a static, subdued level. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation: none !important;
  }

  body::before {
    opacity: 0.3;
  }
}

/* ── Responsive ─────────────────────────────────── */

@media (width <= 640px) {
  .site-nav {
    gap: 1.2rem;
  }

  .projects-grid {
    grid-template-columns: 1fr;
  }

  main {
    padding: 2.5rem 0;
  }
}

